sys_script_include.script:
var BillingUtils = Class.create();
BillingUtils.prototype = {
    initialize: function() {
		this.source = new GlideRecord('u_billing');
    },

	calculateTotalAmount : function(patId){
		var totalAmount = 0;
		this.source.addQuery('u_patient_id', patId);
		this.source.query();
		while(this.source.next()){
			total_amount += this.source.u_total_amount;
		}

		return total_amount;
	},

	checkIfOverdue : function(billId){
		this.source.get(billId);
		if(this.source.u_status == 'overdue'){
			return true;
		}
		else{
			return false;
		}
	},

	fetchBillingDetailsByBillingId : function(billId){
		this.source.get(billId);
		var results = {
			bill_num : this.source.getValue('number'),
			bill_pat_id : this.source.getValue('u_patient_id'),
			bill_app_id : this.source.getValue('u_appointment_id'),
			bill_amount : this.source.getValue('u_total_amount'),
			bill_stat : this.source.getValue('u_status')
		};

		return results;
	},

	fetchBillingRecordByPatientId : function(patId){
		this.source.addQuery('u_patient_id', patId);
		this.source.query();
		return this.source;
	},

    type: 'BillingUtils'
};
